// there is no such row.
func (r *GraphQLGroupRepository) purge(ctx context.Context, id, name string, askReferrers bool) (kept bool, err error) {
	if askReferrers && r.Refs.KeepOnPurge(ctx, "the-protobuf-project.org/Group", name) {
		return true, nil
	}
	err = r.remove(ctx, id)
	if repox.IsForeignKeyViolation(err) {
		r.Refs.Kept(ctx, name, "foreign key")
		return true, nil
	}
	return false, err
}

// PurgeExpired removes for good every deleted record whose expire_time is at
// or before now, keeping the ones something still refers to (see purge).
// Hooks do not run.
func (r *GraphQLGroupRepository) PurgeExpired(ctx context.Context, now time.Time) (repox.PurgeResult, error) {
	var res repox.PurgeResult
	in := repox.ListInput{
		PageSize:    500,
		ShowDeleted: true,
		ReadMask:    []string{"name"},
		Where: []filterx.Condition{
			{Field: "delete_time", Op: filterx.OpNull, Value: "false"},
			{Field: "expire_time", Op: filterx.OpLte, Value: now.UTC().Format(time.RFC3339Nano)},
		},
	}
	for {
		page, next, err := r.list(ctx, in)
		if err != nil {
			return res, err
		}
		for _, m := range page {
			id, err := r.rowID(ctx, m.GetName())
			if errors.Is(err, repox.ErrNotFound) {
				continue // gone since the page was read
			}
			if err != nil {
				return res, err
			}
			kept, err := r.purge(ctx, id, m.GetName(), true)
			switch {
			case errors.Is(err, repox.ErrNotFound):
			case err != nil:
				return res, err
			case kept:
				res.Kept = append(res.Kept, m.GetName())
			default:
				res.Purged = append(res.Purged, m.GetName())
			}
		}
		if next == "" {
			return res, nil
		}
		in.PageToken = next
	}
}

// remove deletes row id with the value-object rows it owns.
func (r *GraphQLGroupRepository) remove(ctx context.Context, id string) error {
	resp, err := r.Svc.Mutation.Scimgroup.Groups.Delete(ctx, id)
	if err != nil {
		return mapGraphQLErr(err)
	}
	if resp.AffectedRows == 0 {
		return repox.ErrNotFound
	}
	dtx := r.Svc.Mutation.Tx()
	{
		rows5, err := r.Svc.Query.Scimgroup.Members.List(ctx, membersql.List().Where(membersql.GroupId.Eq(id)))
		if err != nil {
			return mapGraphQLErr(err)
		}
		for i := range rows5 {
			if id := rows5[i].Id; id != "" {
				got6, err := r.Svc.Query.Scimgroup.Members.Get(ctx, id)
				if err != nil {
					return mapGraphQLErr(err)
				}
				if got6 != nil {
					dtx.Add(r.Svc.Mutation.Scimgroup.Members.DeleteOp(got6.Id, new(membersql.DeleteScimgroupMembersByIdResponse)))
				}
			}
		}
	}
	if err := dtx.Commit(ctx); err != nil {
		return mapGraphQLErr(err)
	}
	return nil
}

// ListByKeys reads every record whose filter field field is one of keys; see
// repox.ListByKeys.
func (r *GraphQLGroupRepository) ListByKeys(ctx context.Context, field string, keys []string, in repox.ListInput) ([]*groupv1.Group, error) {
	return repox.ListByKeys(ctx, field, keys, in, func(ctx context.Context, in repox.ListInput) ([]*groupv1.Group, string, error) {
		return r.List(ctx, in)
	})
}

// Compile-time proof the adapter satisfies the interface.
var _ GroupRepository = (*GraphQLGroupRepository)(nil)

// graphQLBatch is Batch on GraphQL: queued writes go into the Unit's mutation
// request on Commit (see repox.Unit.Commit). A guarded UpdateOutputOnly runs
// ahead of it, one by one: the engine reports its failed guard by touching no
// row, which cannot abort a request.
type graphQLBatch struct {
	u         *repox.Unit
	svc       *freebusyql.Service
	retention time.Duration
	// keys holds the row key of every record this batch creates, by name: a
	// later write in the batch finds its row here, since it is not stored
	// until the batch's request runs.
	keys map[string]string
}

// Commit applies the Unit's writes; see repox.Unit.Commit.
func (b *graphQLBatch) Commit(ctx context.Context) error { return b.u.Commit(ctx) }

// rowID returns the row key of the record named name: one this batch creates,
// else what resolve (a repository's rowID) finds.
func (b *graphQLBatch) rowID(ctx context.Context, name string, resolve func(context.Context, string) (string, error)) (string, error) {
	if id, ok := b.keys[name]; ok {
		return id, nil
	}
	return resolve(ctx, name)
}

// CreateGroup queues a create and returns the name the record will have.
func (b *graphQLBatch) CreateGroup(in *groupv1.Group) (string, error) {
	r := &GraphQLGroupRepository{Svc: b.svc}
	ci, named, err := r.newInput(in)
	if err != nil {
		return "", err
	}
	if b.keys == nil {
		b.keys = map[string]string{}
	}
	b.keys[named.GetName()] = ci.Id
	queueGroupReferences(b.u, named, nil)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		return r.insertOps(ctx, ops, named, ci)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Group", Name: named.GetName(), Op: repox.ChangeCreate, Record: named})
	return named.GetName(), nil
}

// UpdateGroup queues Update; in.Etag, when set, guards it inside the
// batch's request (see updateOps).
func (b *graphQLBatch) UpdateGroup(in *groupv1.Group, paths []string) {
	if _, err := repox.SplitName(in.GetName(), "groups"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLGroupRepository{Svc: b.svc}
	queueGroupReferences(b.u, in, paths)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		return r.updateOps(ctx, ops, id, in, paths, nil)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Group", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getGroup)})
}

// UpdateGroupWithOutputOnly queues UpdateWithOutputOnly; in.Etag, when
// set, guards it inside the batch's request, as UpdateGroup's does.
func (b *graphQLBatch) UpdateGroupWithOutputOnly(in *groupv1.Group, paths, outputPaths []string) {
	if _, err := repox.SplitName(in.GetName(), "groups"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLGroupRepository{Svc: b.svc}
	queueGroupReferences(b.u, in, paths)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		return r.updateOps(ctx, ops, id, in, paths, outputPaths)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Group", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getGroup)})
}

// UpdateGroupOutputOnly queues UpdateOutputOnly; in.Etag, when set, guards
// it, and a guarded update runs ahead of the batch (see graphQLBatch).
func (b *graphQLBatch) UpdateGroupOutputOnly(in *groupv1.Group, paths []string) {
	if len(paths) == 0 {
		b.u.Fail(fmt.Errorf("%w: UpdateOutputOnly needs the fields to write", repox.ErrInvalidArgument))
		return
	}
	if _, err := repox.SplitName(in.GetName(), "groups"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLGroupRepository{Svc: b.svc}
	patch := groupToOutputPatch(in, paths)
	patch.Etag = graphql.Value(repox.NewULID())
	patch.UpdateTime = graphql.Value(tsToStr(timestamppb.New(time.Now().UTC())))
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Group", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getGroup)})
	if etag := in.GetEtag(); etag != "" {
		b.u.QueueGraphQLAhead(func(ctx context.Context) error {
			id, err := b.rowID(ctx, in.GetName(), r.rowID)
			if err != nil {
				return err
			}
			_, err = b.svc.Mutation.Scimgroup.Groups.UpdateIfMatch(ctx, id, patch, groupsql.Etag.Eq(etag))
			return mapGraphQLErr(err)
		})
		return
	}
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.Scimgroup.Groups.UpdateOp(id, patch, new(groupsql.UpdateScimgroupGroupsByIdResponse)))
		return nil, nil
	})
}

// DeleteGroup queues a soft delete. A record already deleted or gone is
// not an error.
func (b *graphQLBatch) DeleteGroup(name string) {
	if _, err := repox.SplitName(name, "groups"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLGroupRepository{Svc: b.svc, Retention: b.retention}
	queueGroupDelete(b.u, name, false)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, name, r.rowID)
		if errors.Is(err, repox.ErrNotFound) {
			return nil, nil
		}
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.Scimgroup.Groups.UpdateOp(id, r.deletePatch(), new(groupsql.UpdateScimgroupGroupsByIdResponse), groupsql.Update().PreCheck(groupsql.DeleteTime.IsNull(true))))
		return nil, nil
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Group", Name: name, Op: repox.ChangeDelete, LoadPrior: repox.PriorOf(name, getGroup)})
}

// PurgeGroup queues the record's removal for good. A record already
// gone is not an error.
func (b *graphQLBatch) PurgeGroup(name string) {
	if _, err := repox.SplitName(name, "groups"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLGroupRepository{Svc: b.svc}
	// A record a referrer in another database or service names is kept, as
	// Purge keeps it. One a foreign key of this database still names fails
	// the commit with repox.ErrForeignKey: the request is one transaction,
	// and the engine cannot skip one of its mutations.
	keep := queueGroupPurge(b.u, name)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		if *keep {
			return nil, nil
		}
		id, err := b.rowID(ctx, name, r.rowID)
		if errors.Is(err, repox.ErrNotFound) {
			return nil, nil
		}
		if err != nil {
			return nil, err
		}
		return r.purgeOps(ctx, ops, id)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Group", Name: name, Op: repox.ChangePurge, LoadPrior: repox.PriorOf(name, getGroup)})
}
